const input = $('Receive Task Search Request').first().json;

const employeeId = input.employee_id || '';
const status = input.status || '';
const priority = input.priority || '';
const overdueOnly = input.overdue_only === true;

const now = new Date();

const tasks = $input.all()
  .map(item => item.json)
  .filter(task => {
    if (employeeId && task.assigned_employee_id !== employeeId) return false;
    if (status && task.status !== status) return false;
    if (priority && task.priority !== priority) return false;

    if (overdueOnly) {
      const dueDate = new Date(task.due_date);
      if (
        !task.due_date ||
        Number.isNaN(dueDate.getTime()) ||
        dueDate >= now ||
        ['Completed', 'Cancelled'].includes(task.status)
      ) {
        return false;
      }
    }

    return true;
  });

return [{
  json: {
    success: true,
    total: tasks.length,
    filters: {
      employee_id: employeeId || null,
      status: status || null,
      priority: priority || null,
      overdue_only: overdueOnly
    },
    tasks
  }
}];
